import type { Guide } from "./blog-types";

export const GUIDES: Guide[] = [
  {
    slug: "how-to-find-scholarships",
    seoTitle: "How to find scholarships",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to find scholarships you can actually apply for",
    description: "Build a useful scholarship shortlist with a search order, eligibility checks and a way to choose what to apply for first.",
    category: "Finding scholarships",
    topics: ["college-merit-scholarships", "outside-scholarships"],
    related: ["how-to-find-new-scholarships", "how-to-find-local-scholarships", "automatic-merit-scholarships", "scholarship-deadline-tracker"],
    intro: ["A scholarship search can turn into forty open tabs and no finished applications. Start by sorting out which awards fit you and which deserve an afternoon of work.", "Start with the colleges you're considering, then look for outside awards with requirements you meet. Keep only opportunities you can explain in one sentence: why you're eligible, what you'd need to submit and when it's due."],
    sections: [
      { id: "profile", title: "Write down your search filters first", paragraphs: ["Make a short reference note with your graduation year, home state, citizenship or residency category, intended degree and possible majors. Add activities you could discuss with some detail, including paid work and family responsibilities. You don't need an impressive label for everything you've done.", "Keep academic facts precise. A weighted school GPA, an unweighted GPA and a college's recalculated GPA may be different numbers. If an award names a particular measure, check that measure rather than choosing the highest number on your transcript."], list: ["Separate facts you can document from interests you might pursue.", "Record whether you're applying as a first-year, transfer or current college student.", "Flag eligibility questions before spending time on an essay."] },
      { id: "colleges", title: "Search each college's own scholarship pages", paragraphs: ["For every college on your list, find its admissions scholarship page and financial aid page. Look for automatic awards, competitive programs and department awards. Read the instructions for your entry year. A page still showing a previous class can help you identify a program, but it cannot confirm this year's deadline.", "Follow the application path all the way to the requirements. A scholarship may use the admissions application, require a separate form or involve a nomination. Write down the step that actually gets you considered. Our [college merit scholarship directory](/scholarships/topics/college-merit-scholarships) can help you find programs; the college's current instructions settle the details."] },
      { id: "outside", title: "Then widen the search", paragraphs: ["Try your school counselor, local foundations and organizations connected to your work or interests. Federal Student Aid lists [schools, community organizations and employers among places to find scholarships](https://studentaid.gov/articles/scholarship-tips/). These are leads to investigate, not promises of funding.", "Search with a specific connection: your county plus scholarship, your employer plus education award, or your intended field plus undergraduate scholarship. Save the sponsor's own page, not just a result from a directory. If you only find an old announcement, put the award in a separate 'check later' list."] },
      { id: "shortlist", title: "Give every potential application a quick reality check", table: { headers: ["Question", "What to record"], rows: [["Do I qualify?", "The exact requirement and where I meet it"], ["Is this cycle open or announced?", "Application year and official deadline"], ["What is the work?", "Essay, recommendation, transcript, project or interview"], ["What would the award cover?", "Amount, permitted expenses and renewal terms"], ["What am I missing?", "One specific question or document"]] }, paragraphs: ["Use a small first shortlist, perhaps five awards. That number is a starting point for managing your time, not a rule about how many scholarships you should pursue. A short application you can submit accurately may deserve attention before a larger award that requires a project you haven't started.", "Don't invent winning odds from the award amount or the size of the sponsor. Unless the provider publishes useful selection data, you don't know your probability. Prioritize clear eligibility, relevant experience and manageable work instead."] },
      { id: "next", title: "End each search session with a next action", paragraphs: ["Before closing your browser, assign one action to every saved opportunity: request a transcript, ask a question, outline an essay or submit a completed form. 'Apply someday' is too vague to help next week.", "Keep the official link beside the deadline. Use the [deadline tracker](/blog/scholarship-deadline-tracker) to record what remains, and the [new-scholarship search routine](/blog/how-to-find-new-scholarships) when you are ready to add more opportunities."] },
    ],
  },
  {
    slug: "merit-vs-need-based-scholarships",
    seoTitle: "Merit vs. need-based scholarships",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "Merit vs. need-based scholarships: what the labels tell you",
    description: "Understand merit aid, need-based aid and awards that consider both, then check which applications and financial forms you need.",
    category: "Understanding awards",
    topics: ["college-merit-scholarships", "outside-scholarships"],
    related: ["scholarships-for-middle-income-families", "full-ride-vs-full-tuition", "compare-scholarship-offers", "how-to-find-scholarships"],
    intro: ["Merit scholarships recognize qualifications such as academic achievement, talent or service. Need-based awards consider financial circumstances. A student can qualify for both, depending on the program.", "The label is a useful starting point. The eligibility rules, required forms and final aid offer tell you what the award means for your situation."],
    sections: [
      { id: "merit", title: "Merit aid recognizes something about your work or abilities", paragraphs: ["Academic achievement is one possible basis for merit aid. A provider may also look at a particular talent, a project, leadership or service. Don't assume that every merit scholarship uses a GPA cutoff, or that meeting a cutoff guarantees selection.", "For a concrete example, [Vanderbilt describes its merit scholarships](https://www.vanderbilt.edu/scholarships/) as recognizing exceptional accomplishment and intellectual promise. Its page says financial need is not a factor unless otherwise indicated. That is Vanderbilt's policy, not a definition that every other provider must follow.", "When reading a program page, separate eligibility from selection. 'Applicants must have a 3.5 GPA' tells you who may apply. It doesn't tell you how the committee chooses among eligible applicants. Look for the selection criteria elsewhere on the page."] },
      { id: "need", title: "Need-based aid uses financial information", paragraphs: ["Need-based assistance depends on an assessment of financial circumstances. The required forms and the calculation depend on the aid program and institution. Don't decide that you qualify or don't qualify from a single income figure on social media.", "Federal Student Aid's [financial aid dictionary](https://studentaid.gov/articles/financial-aid-dictionary/) explains terms such as cost of attendance, grants and net price. Use those definitions to read an offer, then use the college's instructions to identify the forms it requires.", "It is worth checking a college's aid policy before ruling it out because of the sticker price. It is equally important not to treat an estimate as an award. Keep a net price calculator result, an admissions scholarship estimate and an actual financial aid offer clearly labeled in your notes."] },
      { id: "overlap", title: "Some applications ask about both", paragraphs: ["An award can ask for evidence of achievement and financial information. Read that combination literally. Don't skip a financial section because the scholarship has 'merit' in its name, and don't assume an essay about service means need is irrelevant.", "If a form is unclear, ask the provider what it uses to establish financial eligibility and whether the requested document is required for every applicant. Avoid sending financial records to an unverified contact just to get a quick answer."], list: ["Who makes the award: the college, a government program or an outside organization?", "What determines eligibility, and what determines selection?", "Which financial forms are required, if any?", "Does consideration happen automatically, or is there another application?", "How does the award interact with other aid?"] },
      { id: "college", title: "Don't assume every college offers merit scholarships", paragraphs: ["[Yale states that it does not award merit-based scholarships](https://finaid.yale.edu/outsideresources). Students can still pursue outside awards, and Yale explains how those resources may affect its aid offer. A strong student applying there should read Yale's financial aid policy rather than search for a nonexistent general academic merit application.", "Make a college-by-college table with columns for institutional merit aid, need-based forms and outside award reporting. Leave a cell marked 'unconfirmed' when you haven't found the answer. That is more useful than filling it with an assumption."] },
      { id: "decision", title: "Compare the resulting price", paragraphs: ["An impressive scholarship name doesn't tell you what your family would pay. Compare the school's total estimated costs with the grants and scholarships actually offered. Keep loans and work earnings separate.", "If two offers are hard to compare, use our [award comparison walkthrough](/blog/compare-scholarship-offers). It uses fictional numbers to show why a larger scholarship can still leave a higher remaining cost."] },
    ],
  },
  {
    slug: "full-ride-vs-full-tuition",
    seoTitle: "Full ride vs. full tuition scholarships",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "Full ride vs. full tuition: which college costs are covered?",
    description: "Read scholarship coverage carefully, calculate the costs left after full tuition and ask useful questions about housing, fees and renewal.",
    category: "Understanding awards",
    topics: ["full-tuition-scholarships", "college-merit-scholarships"],
    related: ["national-merit-scholarships", "out-of-state-merit-scholarships", "compare-scholarship-offers", "scholarship-renewal-requirements", "merit-vs-need-based-scholarships"],
    intro: ["A full-tuition scholarship pays tuition under the award's terms. It can still leave a substantial bill for housing, meals, fees and other expenses. A 'full ride' may cover more, but you need the provider's definition before comparing offers.", "Treat 'full ride' as a reason to read the coverage details. The phrase alone is not enough to build a four-year budget."],
    sections: [
      { id: "terms", title: "Read the list of covered expenses", paragraphs: ["For any scholarship advertised as full tuition, look for the definition of tuition and any limits. Ask whether mandatory fees are included, whether the award follows tuition increases and whether it covers your intended program. A fixed dollar award and a promise to cover tuition can behave differently over several years.", "A program described as a full ride may list housing, meals or other support in addition to tuition. Check that list against the college's published cost of attendance. Federal Student Aid explains that [cost of attendance includes more than tuition](https://studentaid.gov/articles/financial-aid-dictionary/), including living expenses, books and supplies.", "Don't add a benefit because it sounds like something a full ride should include. If travel, health insurance or summer housing isn't addressed, mark it as a question."] },
      { id: "example", title: "A full-tuition example with a remaining cost", paragraphs: ["Here is a fictional annual budget. These numbers are for explanation and do not represent a particular college or scholarship."], table: { headers: ["Expense", "Annual cost", "Covered by this example award"], rows: [["Tuition", "$32,000", "$32,000"], ["Required fees", "$2,000", "$0"], ["Housing and meals", "$14,000", "$0"], ["Books and supplies", "$1,000", "$0"], ["Travel and personal expenses", "$3,000", "$0"], ["Total", "$52,000", "$32,000"]] }, paragraphsAfter: ["The remaining estimated cost is $20,000 for the year. Some expenses might be billed directly by the college; others would be paid separately. The award is still worth $32,000 in this example. It just doesn't make the whole year free.", "Build your own version with the school's current figures. If you will commute, use the school's applicable budget and your actual travel needs rather than copying an on-campus housing estimate without checking it."] },
      { id: "extras", title: "Separate annual support from extra benefits", paragraphs: ["Some programs combine tuition with a stipend for a specific purpose. For example, [Vanderbilt describes full-tuition awards plus summer stipends](https://www.vanderbilt.edu/scholarships/) for recipients of its signature scholarships. A research or study-abroad benefit should not be counted as unrestricted money for every semester's rent.", "In your notes, give each benefit its own row: annual tuition, housing allowance, one-time equipment support, summer funding or travel reimbursement. Record restrictions and whether you must apply separately to use it. This helps you avoid counting the same dollar twice."] },
      { id: "questions", title: "Ask about the years after your first year", list: ["How many semesters are covered, and does summer enrollment use one?", "What GPA and credit completion rules apply?", "Does the award cover a fifth year if my degree takes longer?", "Can I change majors, study abroad or take an approved leave?", "Will another scholarship change this award or other financial aid?", "When is each payment credited, and what must I pay before then?"], paragraphs: ["Send these questions to the office responsible for the award and keep the written answer with your award letter. A friend's experience under an older scholarship agreement may not apply to your entering class."] },
      { id: "search", title: "Search by coverage, then compare the details", paragraphs: ["Use our [full-tuition scholarship collection](/scholarships/topics/full-tuition-scholarships) to find leads. Read each provider's page before treating its listed value as money you can count on.", "When an offer arrives, compare remaining costs and [renewal conditions](/blog/scholarship-renewal-requirements) together. An affordable first year is only one part of an affordable degree."] },
    ],
  },
  {
    slug: "automatic-merit-scholarships",
    seoTitle: "Automatic merit scholarships: how they work",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "Automatic merit scholarships: automatic award or automatic review?",
    description: "Learn the difference between published merit award criteria and automatic consideration, including deadline and test-score checks.",
    category: "Finding scholarships",
    topics: ["automatic-merit-scholarships", "college-merit-scholarships"],
    related: ["scholarships-by-gpa", "scholarships-without-sat-act", "merit-scholarship-deadlines", "how-to-find-scholarships", "scholarship-deadline-tracker"],
    intro: ["'Automatically considered' means your application enters a review process without a separate scholarship application. 'Automatically awarded' may describe funding tied to published requirements. Read which promise the college is making.", "Before putting an automatic merit scholarship into your college budget, find the exact wording and read every condition attached to it."],
    sections: [
      { id: "difference", title: "Find out what the automatic part refers to", table: { headers: ["Wording", "What to check next"], rows: [["Automatically considered", "How recipients are selected and whether awards are competitive"], ["No separate application", "Which admissions deadline and materials trigger consideration"], ["Published award table", "All eligibility rules, award limits and the correct entering year"], ["Renewable", "Requirements for keeping it after enrollment"]] }, paragraphs: ["A college can use the admissions application to choose a small group of scholarship recipients. The absence of another form makes applying simpler; it does not establish your chance of receiving the award.", "If a page uses vague language such as 'eligible for up to,' don't treat the maximum as your confirmed amount. Ask how your award would be determined and wait for the school's written decision."] },
      { id: "examples", title: "Two official examples show the distinction", paragraphs: ["The University of Alabama publishes [automatic merit scholarship information for out-of-state and international first-year applicants](https://afford.ua.edu/scholarships/oos-international-freshman/). Its process uses academic requirements and the undergraduate application. Check the table for your entering year and the instructions for submitting the records it requires.", "[USC Viterbi's application page](https://viterbiadmission.usc.edu/apply/) describes automatic merit scholarship consideration for applicants who meet its relevant early application requirements. That describes consideration for a competitive award, not a guaranteed scholarship. Other USC schools may have different application options, so use the instructions for your chosen school.", "These examples are useful because the wording changes what you should do with the information. A published award framework can help you investigate a likely cost; a competitive review should remain an uncertain possibility until the award is confirmed."] },
      { id: "scores", title: "Check scholarship rules separately from admission rules", paragraphs: ["Don't infer scholarship testing requirements from a college's general admissions testing policy. Alabama's [admissions FAQ](https://admissions.ua.edu/faqs/) distinguishes test-optional admission from the scores needed for its automatic merit route. It also explains which scores it uses.", "For any college, record whether scores must be official, whether a particular test date is the last accepted date and whether superscores are used. Do the same for GPA: which transcript, which scale and which courses count? If you cannot tell, send the scholarship office the specific question before relying on your calculation."] },
      { id: "checklist", title: "Build a one-page eligibility record", list: ["Entering term and first-year or transfer status", "Residency or citizenship category used for the award", "GPA definition and required transcript", "Testing requirements, if any", "Admission, scholarship and document deadlines", "Award amount or selection process", "Restrictions on combining awards", "Renewal conditions and number of funded semesters"], paragraphs: ["Save the official page or award terms with the date you checked them. If the provider updates the chart later, you'll have a record of what you read. The current written policy and your award agreement still control; a saved screenshot is not a substitute for clarification.", "Mark missing items as unanswered. A table that appears to match your profile can still have a footnote about program, campus or enrollment status."] },
      { id: "next", title: "Finish the required steps early", paragraphs: ["Once you've found an appropriate program, work backward from its document deadline. Request records, check the admissions portal and confirm that required items were received. Submitting a form doesn't necessarily mean every supporting item has arrived.", "Browse [automatic merit scholarship leads](/scholarships/topics/automatic-merit-scholarships), then read the provider's requirements. Our [GPA guide](/blog/scholarships-by-gpa) explains how to interpret academic cutoffs, and the [merit deadline guide](/blog/merit-scholarship-deadlines) helps separate the dates for admission, scholarships and supporting records."] },
    ],
  },
  {
    slug: "how-to-find-local-scholarships",
    seoTitle: "How to find local scholarships",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to find local scholarships without chasing old listings",
    description: "Search counselors, community foundations and local organizations, then verify the application year, eligibility and submission instructions.",
    category: "Finding scholarships",
    topics: ["outside-scholarships"],
    related: ["how-to-find-new-scholarships", "leadership-community-service-scholarships", "how-to-find-scholarships", "scholarship-scams", "scholarship-recommendation-letter"],
    intro: ["Local scholarships turn up on school pages, foundation portals and community announcements. Finding a promising award is the first hurdle. Working out whether the application is from this year or five years ago is sometimes the second.", "A useful local search has two jobs: find the organizations connected to your community, and confirm which opportunities are current."],
    sections: [
      { id: "map", title: "Start with places you have a real connection to", paragraphs: ["Write down your high school, district, town and county. Add employers in your household, clubs you belong to and community organizations where you've participated. These connections are search leads, not automatic proof that you qualify.", "Federal Student Aid suggests [counselors, community groups and employers as scholarship resources](https://studentaid.gov/articles/scholarship-tips/). Ask your counselor whether the school keeps a current local list or receives applications that aren't posted on a public page.", "Be specific when you ask. 'Do you have this year's local scholarship packet, and are any awards nominated through the school?' is easier to answer than 'Do you know any scholarships?' If a packet exists, check whether each award uses the same deadline or its own."] },
      { id: "queries", title: "Use search terms that narrow the geography", list: ["Your county name + community foundation + scholarships", "Your school district + graduating seniors + scholarships", "Your town + scholarship application + your graduation year", "Your employer or a parent's employer + employee dependent scholarship", "Your professional interest + your state + undergraduate scholarship"], paragraphs: ["Try nearby regional foundations as well as organizations named after your town. Geographic eligibility may be based on where you live, where you attend school or another definition. Read that definition instead of deciding from the organization's name.", "Avoid assuming a smaller geographic area means easy selection. You may not know the number of applicants, awards or eligibility restrictions. A local opportunity is useful when you fit it and can complete the application well."] },
      { id: "foundations", title: "Check whether one portal handles multiple awards", paragraphs: ["The [Arizona Community Foundation application page](https://www.azfoundation.org/scholarship-seekers/how-to-apply/) describes a general application that matches students to scholarship opportunities. Individual awards still have their own requirements. This is an example of a search structure worth checking for in your region, not a claim that its application is open today.", "If a foundation uses one portal, look for follow-up questions or supplemental applications after you finish the general form. Save the list of awards you actually applied for. Being matched with an opportunity may be different from completing every required step."] },
      { id: "verify", title: "Check the year before writing anything", paragraphs: ["Old PDF forms can remain visible long after a deadline passes. Compare the year on the form, the announcement date and the live application portal. An undated page with a familiar month and day still needs confirmation.", "If you find conflicting dates, contact the organization through the contact details on its official website. Ask which form and deadline apply to your graduating class. Keep the response with your application record."], list: ["Confirm the sponsor and official website.", "Check the current application cycle.", "Read residency, school and enrollment requirements.", "Check whether nomination or school submission is required.", "Record the delivery method, including any received-by requirement."] },
      { id: "followthrough", title: "Keep the local search small enough to finish", paragraphs: ["Set aside one session for finding opportunities and another for applications. Once you have a few verified matches, stop adding tabs long enough to complete one. A growing list is not useful if every deadline passes while you're still researching.", "When an award needs a recommendation, give your recommender the sponsor's criteria and enough time to respond. Our [recommendation request guide](/blog/scholarship-recommendation-letter) includes a short request template and a practical information packet.", "For awards that haven't announced the next cycle, record a date to check again. Keep that watch list separate from applications with confirmed deadlines."] },
    ],
  },
  {
    slug: "how-to-write-a-scholarship-essay",
    seoTitle: "How to write a scholarship essay",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to write a scholarship essay that sounds like you",
    description: "Choose a specific example, answer the actual prompt and revise for clarity without replacing your own voice or inventing a dramatic story.",
    category: "Applications",
    topics: ["outside-scholarships", "scholarship-competitions"],
    related: ["why-do-you-deserve-this-scholarship", "scholarship-career-goals-essay", "scholarship-essay-about-yourself", "can-you-reuse-scholarship-essays", "scholarship-recommendation-letter"],
    intro: ["A scholarship essay needs a clear answer to the prompt and enough detail for a reader to understand your experience. You can start with a true, ordinary moment. The opening sentence does not have to change anyone's life.", "The strongest starting point is often a specific decision or responsibility. It might come from work, a class, a club or helping at home. The experience doesn't have to sound unusual before you explain it."],
    sections: [
      { id: "prompt", title: "Turn the prompt into a small checklist", paragraphs: ["Copy the prompt above your draft. Underline the actual requests: describe a contribution, explain a challenge, discuss a goal, or connect an experience to the award's purpose. If the prompt asks two questions, your essay needs to answer both.", "Record the word limit and any rules about outside help or AI tools. Follow the provider's rules even if another scholarship permits a different kind of assistance. Don't submit invented experiences or language you cannot honestly stand behind.", "[CU Boulder's scholarship essay guidance](https://www.colorado.edu/scholarships/tips-apply/essay-tips) emphasizes answering the question, using your own voice and getting useful feedback. Use those as editing checks rather than trying to imitate an essay you found online."] },
      { id: "choose", title: "Choose one example you can explain in detail", paragraphs: ["Before drafting, jot down three possible moments. For each, answer: What was happening? What did I do? Why did I choose that action? What happened afterward? The example with the clearest answers may be more useful than the activity with the grandest title.", "Keep the scale honest. If you changed how one club meeting ran, describe that change. Don't turn it into a claim that you transformed your whole school. Small, verifiable details give the reader something to understand.", "You can also describe an unresolved problem. A thoughtful essay doesn't need every difficulty to disappear by the final paragraph. Explain what you understand now and what you still need to work on."] },
      { id: "example", title: "Replace a broad claim with an observable action", paragraphs: ["The following sentences are fictional teaching examples, not a student's experience or text to submit.", "Broad: 'My leadership made a positive impact on our club and taught me the value of teamwork.'", "More specific: 'At the next meeting, I put the supply list on the board and asked each person to claim one job. We found two missing items before everyone left, instead of discovering them on Saturday morning.'", "The second version gives the reader an action and a result. It still needs reflection that fits the prompt. Perhaps the writer learned to ask for help earlier, or realized that the old plan depended on people knowing things nobody had explained. The lesson should come from the actual experience, not from a list of admirable traits."] },
      { id: "draft", title: "Write the middle before worrying about the opening", paragraphs: ["Explain the event in plain language first. Add only the background a reader needs to follow your choices. Then write the sentence that introduces the problem or responsibility. This avoids spending an hour on an opening quotation that the essay never needs.", "When you finish, read the draft aloud. Mark any phrase you would struggle to explain in conversation. Some formal language is fine, but words that hide your meaning should go. Preserve a sentence that sounds natural even if a more elaborate version seems impressive."] },
      { id: "review", title: "Give your reviewer a useful job", list: ["Where did I leave part of the prompt unanswered?", "Which detail was confusing or needed context?", "Where did I repeat an idea?", "Does any claim sound larger than the example supports?", "Which sentences no longer sound like me?"], paragraphs: ["Ask for feedback before asking for a rewrite. Keep control of the facts and final wording. After revising, check the word count in the actual application field; portals can handle formatting differently.", "Save the submitted essay with the award name and date. For a different application, use the [essay reuse guide](/blog/can-you-reuse-scholarship-essays) to decide what still fits. If you are stuck on the prompt itself, try the guides to [career goals](/blog/scholarship-career-goals-essay), [writing about yourself](/blog/scholarship-essay-about-yourself) or [why you deserve the scholarship](/blog/why-do-you-deserve-this-scholarship)."] },
    ],
  },
  {
    slug: "scholarship-recommendation-letter",
    seoTitle: "How to ask for a scholarship recommendation",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to ask for a scholarship recommendation letter",
    description: "Choose someone who knows your work, make a clear request and prepare a short packet with deadlines, criteria and submission instructions.",
    category: "Applications",
    topics: ["outside-scholarships", "college-merit-scholarships"],
    related: ["scholarship-application-checklist", "leadership-community-service-scholarships", "how-to-write-a-scholarship-essay", "scholarship-deadline-tracker", "how-to-find-local-scholarships"],
    intro: ["Choose a recommender who meets the scholarship's rules and has seen your work closely. Their letter can add observations that your activity list cannot: how you handled a difficult task, responded to feedback or helped a group finish.", "A teacher or supervisor who knows your contribution is usually a more useful choice than a prominent person who barely knows you, provided they meet the award's requirements."],
    sections: [
      { id: "choose", title: "Check who is allowed to write the letter", paragraphs: ["Read the application before asking anyone. It may require a teacher in a particular subject, a counselor, an employer or someone outside your family. If the instructions say teacher, don't assume a coach or supervisor can substitute.", "Think about recent situations in which the person saw you solve a problem, follow through on a responsibility or improve over time. You should be able to name a real shared experience. If you cannot, another recommender may have more to say.", "[CU Boulder's recommendation guidance](https://www.colorado.edu/scholarships/tips-apply/getting-good-recommendations) advises choosing someone who knows you and giving at least three weeks' notice. Treat that as a useful planning minimum from one university, not a universal rule. A busy teacher may need longer, especially during application season."] },
      { id: "request", title: "Make the request easy to answer", paragraphs: ["Ask whether the person has time to write a supportive recommendation for this particular opportunity. Include the due date and submission method immediately. Give them a comfortable way to decline so you can ask someone else in time.", "Adapt this request template to your actual relationship:", "Hello [name], I'm applying for [award], which considers [relevant criteria]. Would you have time to write a supportive recommendation by [date]? I thought of you because you saw my work on [specific shared experience]. The letter goes through [submission method]. I can send the instructions and a short background note. I understand if your schedule doesn't allow it.", "Don't leave placeholders in the message you send. If the deadline is close, say so directly and have another plan. Avoid making the person discover the time pressure after agreeing."] },
      { id: "packet", title: "Send a short, organized information packet", list: ["The official award page and selection criteria", "The exact deadline, time zone and submission instructions", "A brief explanation of why you're applying", "A current activity or work summary", "Two or three accurate reminders of work they observed", "Any required form or application identifier"], paragraphs: ["Make the reminders factual. 'I revised the lab analysis after your feedback on the first draft' gives the writer something to remember. 'Please say I'm the best student you've taught' asks them to make a judgment for you.", "If the scholarship asks about a particular quality, you can point to a relevant experience. Let the recommender decide what to write. Don't provide a letter that pretends to be their independent assessment."] },
      { id: "submission", title: "Check the delivery process before the deadline", paragraphs: ["Some applications send an invitation directly to the recommender. Others require a separate upload or a school submission. Enter the correct address, tell the writer what to expect and check whether the portal shows receipt.", "If the letter hasn't arrived, send one polite reminder with the deadline and submission link. A portal status can lag, so phrase it as a check rather than an accusation. If an invitation is missing, ask the provider how to resend it instead of creating duplicate applications.", "Respect any confidentiality instructions. You can confirm that a letter was submitted without demanding to read it."] },
      { id: "after", title: "Close the loop", paragraphs: ["Thank the recommender after submission and share the result when you receive it. If you need another letter later, ask again with the new award's instructions. Permission for one application is not permission to submit someone's name to every portal you find.", "Add the request date, agreed deadline and receipt status to your [scholarship tracker](/blog/scholarship-deadline-tracker). That small record helps you keep your promises and avoids repeated last-minute requests."] },
    ],
  },
  {
    slug: "scholarship-deadline-tracker",
    seoTitle: "Scholarship deadline tracker and template",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "A scholarship deadline tracker that tells you what to do next",
    description: "Download a simple CSV tracker and plan essays, recommendations, documents and receipt checks around each scholarship's real deadline.",
    category: "Applications",
    topics: ["outside-scholarships", "college-merit-scholarships"],
    related: ["merit-scholarship-deadlines", "scholarship-application-checklist", "scholarship-recommendation-letter", "how-to-write-a-scholarship-essay", "automatic-merit-scholarships"],
    intro: ["A deadline tracker is most useful when it tells you what to do today. Put the next action beside the final due date so you can spot requests and unfinished work before they become urgent.", "Keep the system simple enough that you'll update it. A spreadsheet with an official link, a deadline, a next action and a status can handle a small scholarship search without another app."],
    sections: [
      { id: "download", title: "Start with a blank tracker", paragraphs: ["[Download the scholarship tracker CSV](/resources/scholarship-tracker.csv) and open it in Excel, Google Sheets or another spreadsheet app. It contains column headings, with no account or personal information required.", "Use one row per application. If a general application unlocks several supplemental awards, give those supplements separate rows when they have separate work or deadlines. A single 'foundation application' row can hide unfinished requirements.", "Don't put passwords, Social Security numbers or financial documents in this sheet. Store sensitive records through the provider's approved process and use the tracker to record whether they were submitted."] },
      { id: "fields", title: "Record the deadline you actually have to meet", table: { headers: ["Field", "Why it helps"], rows: [["Official URL and cycle", "Distinguishes the current application from an old listing"], ["Deadline and time zone", "Avoids assuming midnight in your own location"], ["Eligibility checked", "Prevents work on a known mismatch"], ["Required materials", "Makes dependencies visible"], ["Next action and target date", "Turns the row into a task"], ["Submission and receipt status", "Separates sending from successful delivery"], ["Renewal terms", "Keeps future conditions beside the award"]] }, paragraphs: ["Read whether the deadline applies to submission, receipt or a postmark. If the page only gives a date, ask for clarification when timing matters. Don't invent a time zone or assume that a late recommendation will be accepted.", "Federal Student Aid recommends [keeping scholarship applications organized](https://studentaid.gov/articles/scholarship-tips/). The fields here are a practical way to do that; they aren't extra requirements imposed by scholarship providers."] },
      { id: "backward", title: "Work backward from the slowest dependency", paragraphs: ["An essay is under your control. A transcript, nomination or recommendation may depend on someone else's schedule. Request those items first and record the date you asked. Give the person the real deadline, along with an earlier preferred completion date if helpful.", "For a recommendation, our [request guide](/blog/scholarship-recommendation-letter) explains what to send. Don't treat the illustrative two-week plan below as enough notice for a new letter. It assumes any outside documents have already been requested."], list: ["Two weeks before: confirm eligibility and requirements; outline the written responses.", "One week before: finish a draft and check supporting-document status.", "Several days before: revise, proofread and prepare files in the required format.", "Before the final day: submit if everything is ready and save confirmation.", "After submission: check receipt and any requested follow-up items."] },
      { id: "status", title: "Use statuses that mean one thing", paragraphs: ["Try 'checking eligibility,' 'ready to start,' 'drafting,' 'waiting on document,' 'submitted' and 'receipt confirmed.' An application marked submitted should have a confirmation number, email or other record where the provider supplies one.", "If you stop pursuing an award, mark it 'not pursuing' and add a brief reason. Don't delete the row immediately if it contains a useful official link or an answer you might need next year.", "Once a week, sort by the next-action date. The award with the nearest final deadline isn't always the most urgent task. A recommendation request for a later award may need attention before an essay you can finish yourself."] },
      { id: "finish", title: "Keep a copy of what you submitted", paragraphs: ["Save the final essay, application responses and confirmation in a folder named for the award and cycle. Take care with shared folders if the material contains personal information.", "When a decision arrives, record the outcome and any acceptance deadline. A winner may still need to accept terms, verify enrollment or report the award to the college. The [scholarship payment guide](/blog/how-scholarship-money-is-paid) walks through that handoff."] },
    ],
  },
  {
    slug: "compare-scholarship-offers",
    seoTitle: "How to compare scholarship offers",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to compare scholarship offers without being fooled by the biggest number",
    description: "Compare remaining costs, renewal terms and payment timing with a worked example and a downloadable award comparison worksheet.",
    category: "Understanding awards",
    topics: ["college-merit-scholarships", "full-tuition-scholarships"],
    related: ["merit-scholarship-appeal", "out-of-state-merit-scholarships", "how-scholarship-money-is-paid", "full-ride-vs-full-tuition", "scholarship-renewal-requirements", "merit-vs-need-based-scholarships"],
    intro: ["A $30,000 scholarship sounds better than a $15,000 scholarship. You could still pay more at the first college if its starting price is much higher. Compare the cost left after grants and scholarships, then check the conditions attached to each offer.", "Put the offers beside the costs before deciding which is stronger. Then look at the conditions that could change the comparison after your first year."],
    sections: [
      { id: "same", title: "Put both offers on the same basis", paragraphs: ["Use the same time period for each college, usually one academic year. Check whether an impressive scholarship total covers one year or all four. Separate confirmed aid from awards you're still competing for.", "Federal Student Aid's [guide to evaluating aid offers](https://studentaid.gov/articles/evaluating-financial-aid-offers/) recommends comparing costs and distinguishing grants from loans and money earned through work. A loan helps finance a price; it doesn't reduce that price in the same way as a scholarship.", "[Download the award comparison CSV](/resources/award-comparison.csv) to record the two colleges side by side. It includes the fictional example below and blank columns for your own offers. Replace the examples with current figures before using it to make a decision."] },
      { id: "example", title: "A smaller scholarship can leave a lower price", paragraphs: ["This example uses invented colleges and annual figures. It is a calculation exercise, not an estimate of your aid."], table: { headers: ["Annual amount", "Example College A", "Example College B"], rows: [["Total estimated cost of attendance", "$60,000", "$38,000"], ["Confirmed scholarships and grants", "$30,000", "$15,000"], ["Remaining estimated cost", "$30,000", "$23,000"]] }, paragraphsAfter: ["College B's scholarship is $15,000 smaller, but its remaining estimated cost is $7,000 lower. The calculation subtracts grants and scholarships from the total estimated cost. It does not subtract loans or assume a student will earn a particular amount at work.", "Check what each college includes in its estimate. A missing travel allowance or a different housing arrangement can make a comparison look cleaner than it really is. Keep a note beside any figure you've adjusted."] },
      { id: "cash", title: "Separate the annual price from the timing of payments", paragraphs: ["A total annual estimate doesn't explain when you need money available. Ask which costs appear on the college bill, which expenses you'll pay separately and when scholarship funds are credited.", "If an outside scholarship is paid later, ask the college how it handles that timing. Don't assume an award letter automatically postpones a bill. Keep the provider's payment instructions and the college's answer together.", "If the package includes work earnings, consider the job hours, timing and whether the work is secured. Treat an expected income figure as a plan to examine rather than money already credited to your account."] },
      { id: "fouryears", title: "Read the terms that affect later years", list: ["Is the scholarship renewable, and for how many semesters?", "Is it a fixed amount or tied to a defined cost such as tuition?", "What GPA, credit completion or enrollment requirements apply?", "Can the amount change when financial circumstances change?", "What happens if you change majors, campuses or housing plans?", "How would an outside scholarship affect other aid?"] },
      { id: "outside", title: "Ask the college how outside awards fit", paragraphs: ["Don't assume that every outside scholarship stacks on top of every other grant. Colleges publish policies for handling outside resources, and you need the policy that applies to your offer. [Yale's outside resources page](https://finaid.yale.edu/outsideresources), for example, explains how awards may affect its Student Share and asks students to report outside resources.", "Send the financial aid office the award's amount, timing and restrictions, then ask for an explanation of any resulting changes. Keep the revised offer, not just your original arithmetic."] },
      { id: "decision", title: "Keep the uncertainty visible", paragraphs: ["Use separate notes for confirmed numbers, estimates and unanswered questions. If affordability depends on winning another competitive scholarship, write that plainly. Don't quietly put the hoped-for award into the confirmed aid column.", "Price is one part of choosing a college. This comparison gives you a clear starting point for discussing the academic program, daily life and financial commitment with the people helping you decide."] },
    ],
  },
  {
    slug: "scholarship-scams",
    seoTitle: "Scholarship scams: warning signs and checks",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How to check whether a scholarship is legitimate",
    description: "Recognize scholarship scam warning signs, verify the sponsor independently and protect account access before sharing sensitive information.",
    category: "Finding scholarships",
    topics: ["outside-scholarships"],
    related: ["how-to-find-new-scholarships", "how-to-find-scholarships", "how-to-find-local-scholarships", "scholarship-deadline-tracker"],
    intro: ["Imagine an unexpected message saying you have won a scholarship. The logo looks familiar, but there is a fee to claim it and a deadline tonight. Pause before replying and find the sponsor through a separate, official route.", "Use the contact information you find on the real organization's website to ask whether the offer exists."],
    sections: [
      { id: "warnings", title: "Treat pressure and payment demands seriously", paragraphs: ["The [Federal Trade Commission's scholarship scam guidance](https://consumer.ftc.gov/articles/how-avoid-scholarship-and-financial-aid-scams) warns about upfront scholarship fees, requests for bank or card information to establish eligibility, and claims that you're a finalist for an award you never entered. A claim that a service can guarantee you a scholarship is another warning sign.", "The FTC also distinguishes paid search services from scholarship awards. Paying someone to search is not proof that you'll receive funding. Don't confuse a service's invoice with an official requirement to apply for or release an award.", "A deadline can be real and still deserve verification. If the sender insists you cannot check with the organization, that is a reason to slow down, not a reason to comply."] },
      { id: "independent", title: "Find the organization without using the message's link", paragraphs: ["Open a new browser tab and find the sponsor's official website independently. Look for the scholarship from the site's own navigation or search. Compare the program name, eligibility, application method and contact information.", "Don't rely only on a familiar logo or a sender display name. Read the full website address. A small spelling change or an unrelated domain can be easy to miss on a phone.", "If you find the organization but not the award, contact it using the number or email published on its official site. Ask whether the scholarship and message are theirs. Do not use the suspicious message's reply address as your only verification method."] },
      { id: "questions", title: "Ask questions that produce checkable answers", list: ["What organization funds and administers this award?", "Where are the eligibility and selection rules published?", "Which application did this notice refer to?", "How and when are funds paid?", "What information is required, and why?", "Where can I confirm this offer through the sponsor's official website?"], paragraphs: ["A professional-looking answer is not the same as independent confirmation. Follow the links from the actual sponsor's site and compare the details. If the answer sends you back to the same unverified form, the original question is still unresolved.", "Keep a short record of what you checked. The goal is to establish who is asking for your information and what process you're entering, not to collect as many reassuring statements as possible."] },
      { id: "information", title: "Share information only through a verified process", paragraphs: ["Before uploading a transcript or financial document, confirm that the form belongs to the provider and that the document is actually required at this stage. A general contact form and an official application portal are not interchangeable.", "Never give another person access to your StudentAid.gov account. The FTC specifically warns against sharing your FSA ID. If someone claims they need your login to obtain a scholarship, use the official support channels instead.", "When you need help checking a form, ask a counselor or trusted adult to look at the page with you. You can discuss the request without forwarding copies of every sensitive document."] },
      { id: "already", title: "If you've already responded", paragraphs: ["Save the message, website address and any payment or submission records. Stop using the unverified contact while you investigate. If you shared a password, change it through the real service's website and follow that service's account recovery guidance.", "The FTC accepts reports at [ReportFraud.ftc.gov](https://reportfraud.ftc.gov/). If money or financial account details were involved, contact the relevant bank or payment provider through its official channel. Use the facts you saved to explain what happened.", "Return to your scholarship search through a verified provider page. Our [search guide](/blog/how-to-find-scholarships) shows how to keep the official source beside each opportunity so you don't have to reconstruct it later."] },
    ],
  },
  {
    slug: "scholarships-for-international-students",
    seoTitle: "Scholarships for international students",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "How international students can search for U.S. scholarships",
    description: "Check citizenship rules, college funding, covered costs and application requirements before building an international scholarship shortlist.",
    category: "Finding scholarships",
    topics: ["international-student-scholarships", "college-merit-scholarships"],
    related: ["scholarships-without-sat-act", "automatic-merit-scholarships", "full-ride-vs-full-tuition", "compare-scholarship-offers"],
    intro: ["For an international student considering a U.S. college, eligibility is only the first question. You also need to know what the scholarship covers and whether it is competitive before using it in your budget.", "Start with the colleges themselves. Then add outside scholarships whose citizenship, residency and enrollment rules match your circumstances."],
    sections: [
      { id: "eligibility", title: "Read the exact citizenship and residency language", paragraphs: ["Use the provider's definition of an international applicant. Don't assume it is identical to the category used by another college, a testing service or a visa form. Read any restrictions on home country, current residence, degree level and location of study.", "Federal aid eligibility is a separate question. [Federal Student Aid lists categories of eligible non-U.S. citizens](https://studentaid.gov/understand-aid/eligibility/requirements/non-us-citizens). Citizenship alone is not enough information to decide every person's eligibility. Use the official guidance and the college's aid office if you need help identifying which rules apply.", "In your shortlist, copy the requirement accurately and record the source. If the page doesn't address your status, mark it as unconfirmed and ask. Don't change an answer on an application to fit a category that seems more favorable."] },
      { id: "colleges", title: "Investigate funding at each college before applying", paragraphs: ["Find the college's pages for international admissions and financial assistance. Check merit awards and any need-based assistance it describes for your applicant category. Look for separate forms, earlier scholarship deadlines and limits by campus or program.", "The University of Alabama, for example, publishes [merit scholarship information that includes international first-year applicants](https://afford.ua.edu/scholarships/oos-international-freshman/). That is a concrete place to examine academic requirements and application steps. It is not evidence that all international applicants receive the same award.", "[EducationUSA's financing resources](https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/undergraduate) are another official starting point for researching U.S. study costs and funding. Use them alongside each institution's current instructions."] },
      { id: "cost", title: "Budget beyond tuition", paragraphs: ["Create a college-specific budget before comparing award amounts. Ask about mandatory fees, housing, meals, health insurance and required deposits. Add realistic travel and personal costs, and note which figures are estimates.", "For an award described as full tuition, verify exactly what tuition includes. A summer research stipend may be restricted to that activity. A one-time allowance may not repeat next year. Our [full tuition vs. full ride guide](/blog/full-ride-vs-full-tuition) shows how a major award can still leave uncovered costs.", "If your household pays in another currency, record the date and exchange rate used for your estimate. Leave room to revisit it. A scholarship stated in U.S. dollars and a family budget in another currency can change in relation to each other."] },
      { id: "documents", title: "Plan for document and payment logistics", list: ["Which transcripts or translations are required, and who may provide them?", "Are test scores required specifically for the scholarship?", "What is the deadline in the provider's time zone?", "How will recommendations be requested and submitted?", "When does the award become official, and when are funds available?", "What additional financial documentation does the college require for enrollment?"], paragraphs: ["Ask these questions early enough to handle delays. Keep immigration and enrollment documentation separate from your scholarship estimate, and follow the college's official instructions for those processes. A scholarship application is not a confirmation that every other requirement has been met."] },
      { id: "shortlist", title: "Build a shortlist with three possible outcomes", paragraphs: ["For each college, record the cost with confirmed funding, the cost if a competitive award is won and the cost if it is not. Don't put the competitive outcome into your only budget.", "Browse our [international student scholarship collection](/scholarships/topics/international-student-scholarships) for leads, then confirm eligibility and the current cycle on the sponsor's site. Keep a separate list of unanswered questions and resolve the ones that determine affordability before committing to a plan.", "When offers arrive, compare their written terms with your original assumptions. The [award comparison worksheet](/blog/compare-scholarship-offers) can help you see which numbers are confirmed and which still need an answer."] },
    ],
  },
  {
    slug: "scholarship-renewal-requirements",
    seoTitle: "Scholarship renewal requirements",
    updatedAt: "2026-10-27T22:59:00Z",
    title: "Scholarship renewal requirements: what to check before accepting",
    description: "Read GPA, credit completion, enrollment and renewal limits before counting a scholarship toward several years of college costs.",
    category: "Understanding awards",
    topics: ["college-merit-scholarships", "automatic-merit-scholarships"],
    related: ["how-scholarship-money-is-paid", "compare-scholarship-offers", "full-ride-vs-full-tuition", "scholarship-deadline-tracker"],
    intro: ["A renewable scholarship can continue for later terms if you meet its conditions. Those might involve grades, completed credits, enrollment or a new form. The award letter should tell you which rules apply.", "Read those conditions before using four years of scholarship money in your college budget. The details matter most when something changes."],
    sections: [
      { id: "agreement", title: "Find the terms for your award and entering year", paragraphs: ["Start with the award letter, acceptance terms and linked policy page. Make sure the policy applies to the scholarship you received. A college may have different rules for central merit awards, department scholarships and other types of aid.", "Save the documents with the date you received them. If an overview page and your award letter seem inconsistent, ask the administering office to explain which terms apply. Don't resolve the conflict by picking the more generous version.", "Record the maximum number of semesters or years and whether summer funding uses part of that limit. Ask about any deadline for accepting or renewing the award."] },
      { id: "gpa", title: "Check both grades and completed credits", paragraphs: ["The University of Alabama's [scholarship policies](https://afford.ua.edu/scholarships/policies/) require recipients of its specified automatic and competitive scholarships to maintain a cumulative 3.0 UA GPA and earn 67% of attempted UA credits. That example shows why looking only at GPA can miss another condition. Other awards may use different rules.", "For your own scholarship, find out whether GPA is checked each term or on another schedule, whether it is cumulative, and which courses enter the calculation. Then check completed-credit requirements separately.", "Don't assume the scholarship rule is identical to the school's academic standing policy or its rules for other financial aid. Ask which standards apply to each award in your package."], list: ["Required GPA and how it is calculated", "Required enrollment status", "Credits that must be attempted or completed", "When progress is reviewed", "Any probation, warning or appeal process"] },
      { id: "changes", title: "Ask before making a change that could affect eligibility", paragraphs: ["Before dropping a class, changing majors, transferring campuses or taking leave, ask how the decision would affect the award. You may have good reasons for the change. Getting the funding answer first helps you make it with complete information.", "Give the office the actual situation: the scholarship name, proposed change, term and relevant deadline. 'Can I drop a course?' may not give enough information for a useful answer. Keep the response in writing when possible.", "Also ask about study abroad, co-op work or a degree plan that extends beyond the standard funded period if those are part of your plans. Don't assume a benefit follows you into every program automatically."] },
      { id: "money", title: "Check whether the amount stays the same", paragraphs: ["A renewable fixed-dollar award can remain unchanged while expenses change. An award tied to tuition may follow a different rule. Read the actual formula and any cap, rather than projecting the first-year percentage across every later year.", "Ask whether other scholarships, enrollment changes or financial information can affect the amount. Our [offer comparison guide](/blog/compare-scholarship-offers) keeps these conditions next to the annual cost so they don't disappear behind the headline award value."] },
      { id: "calendar", title: "Put renewal tasks on the calendar", paragraphs: ["If the scholarship requires a form, progress report, thank-you letter or enrollment confirmation, record the actual instruction and deadline. Don't assume there is a task just because another award required one, but don't overlook it when your terms do.", "Add a reminder before the end of each term to check your award status and read messages from the administering office. If something goes wrong, ask about the published process promptly. An appeal may be available under a policy; approval is not guaranteed.", "Keep the renewal record beside your original application in the [scholarship tracker](/blog/scholarship-deadline-tracker). The point is to make the next requirement visible while you still have time to address it."] },
    ],
  },
];
